import functools

def solve_game(n):
    cards = tuple(range(1, n + 1))

    @functools.lru_cache(None)
    def get_value(remaining_cards, current_sum, turn):
        if not remaining_cards:
            return abs(current_sum)

        if turn == 0:  # Grogg's turn (minimize)
            best_val = float('inf')
            for i in range(len(remaining_cards)):
                card = remaining_cards[i]
                next_cards = remaining_cards[:i] + remaining_cards[i+1:]
                # Grogg can put card in either pile
                val1 = get_value(next_cards, current_sum + card, 1)
                val2 = get_value(next_cards, current_sum - card, 1)
                best_val = min(best_val, val1, val2)
            return best_val
        else:  # Winnie's turn (maximize)
            best_val = float('-inf')
            for i in range(len(remaining_cards)):
                card = remaining_cards[i]
                next_cards = remaining_cards[:i] + remaining_cards[i+1:]
                # Winnie can put card in either pile
                val1 = get_value(next_cards, current_sum + card, 0)
                val2 = get_value(next_cards, current_sum - card, 0)
                best_val = max(best_val, val1, val2)
            return best_val

    return get_value(cards, 0, 0)

for n in range(2, 11, 2):
    print(f"N={n}, result={solve_game(n)}")

